import {
  LEAD_CHAT_LEGACY_EVENTS,
  LEAD_CHAT_SOCKET_EVENTS,
} from '../constants/leadChatApi';

function normalizeType(payload) {
  return `${payload?.type || payload?.event || ''}`.trim();
}

export function parseLeadChatPayload(rawPayload) {
  if (!rawPayload) return null;

  let payload = rawPayload;
  if (typeof rawPayload === 'string') {
    try {
      payload = JSON.parse(rawPayload);
    } catch {
      return null;
    }
  }

  const type = normalizeType(payload);

  if (type === LEAD_CHAT_SOCKET_EVENTS.CHAT_MESSAGE || type === LEAD_CHAT_LEGACY_EVENTS.CHAT_MESSAGES) {
    return { kind: 'message', data: payload.message || payload.data || payload };
  }

  if (type === LEAD_CHAT_SOCKET_EVENTS.MESSAGE_STATUS || type === LEAD_CHAT_LEGACY_EVENTS.STATUS_NOTIFICATION) {
    return { kind: 'status', data: payload.message || payload.data || payload };
  }

  if (type === LEAD_CHAT_SOCKET_EVENTS.SESSION_UPDATED || type === LEAD_CHAT_LEGACY_EVENTS.INTERVENE_STATUS) {
    return { kind: 'session', data: payload.data || payload };
  }

  if (payload.message && (payload.message.phone_number || payload.message.content)) {
    return { kind: 'message', data: payload.message };
  }

  if (payload.w_id && payload.status) {
    return { kind: 'status', data: payload };
  }

  return null;
}
