import React, { useMemo } from 'react';
import { Box, Typography } from '@mui/material';
import { SearchableSelect } from '../../../../components/ui';
import { getFormControlSx } from '../../../../components/ui/Form/controls/formControlStyles';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';

export default function LeadSendTemplateBulkMappingPanel({
  copy,
  styles,
  mappingFields = [],
  columnOptions = [],
  onColumnSelect,
}) {
  const themeTokens = useFeatureTheme();
  const { semantic, typography, controlHeights } = themeTokens;
  const labelSx = styles?.leadSendTemplateParamFieldLabel;
  const cellSx = styles?.leadSendTemplateBulkFieldCell ?? styles?.leadSendTemplateParamFieldCell;

  const selectSx = useMemo(
    () =>
      getFormControlSx(themeTokens, {
        '& .MuiOutlinedInput-root': {
          minHeight: controlHeights.sm,
        },
        '& .MuiFormHelperText-root': {
          display: 'none',
        },
      }),
    [controlHeights.sm, themeTokens]
  );

  const columnSelectOptions = useMemo(
    () =>
      columnOptions.map((option) => ({
        value: option.value,
        label: option.label,
      })),
    [columnOptions]
  );

  if (!mappingFields.length) {
    return (
      <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary }}>
        {copy.direct.noParamsRequired}
      </Typography>
    );
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.25 }}>
      <Box>
        <Typography
          sx={{
            fontSize: typography.fontSizeSm,
            fontWeight: typography.fontWeightSemibold,
            color: semantic.text.primary,
          }}
        >
          {copy.bulk.mapColumnsTitle}
        </Typography>
        <Typography
          sx={{
            fontSize: typography.fontSizeSm,
            color: semantic.text.secondary,
            mt: 0.375,
            lineHeight: 1.5,
          }}
        >
          {copy.bulk.mapColumnsHint}
        </Typography>
      </Box>

      <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
        {mappingFields.map((field) => (
          <Box
            key={field.paramName}
            sx={{
              ...styles?.leadSendTemplateParamRow,
              border: `1px solid ${semantic.borders.border}`,
              borderRadius: 1,
              bgcolor: semantic.surfaces.surfaceSubtle,
            }}
          >
            <Box sx={styles?.leadSendTemplateBulkMapGrid}>
              <Typography
                sx={{
                  ...labelSx,
                  fontWeight: typography.fontWeightSemibold,
                  color: semantic.text.primary,
                }}
              >
                {copy.direct.paramLabel(field.variableIndex, field.label || field.paramName)}
              </Typography>

              {field.isAgentParam ? (
                <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary }}>
                  {copy.bulk.agentParamHint}
                </Typography>
              ) : (
                <Box sx={cellSx}>
                  <SearchableSelect
                    placeholder={copy.bulk.selectColumn}
                    options={columnSelectOptions}
                    value={
                      columnSelectOptions.find((option) => option.value === field.columnKey)
                      ?? null
                    }
                    onChange={(selected) =>
                      onColumnSelect?.(field.paramName, selected?.value ?? '')
                    }
                    labelKey="label"
                    valueKey="value"
                    clearable={false}
                    size="small"
                    sx={selectSx}
                    disabled={!columnSelectOptions.length}
                    slotProps={{
                      popper: {
                        sx: { zIndex: 1500 },
                        placement: 'bottom-start',
                      },
                    }}
                  />
                </Box>
              )}
            </Box>
          </Box>
        ))}
      </Box>
    </Box>
  );
}
