import { useCallback, useEffect, useRef, useState } from 'react';
import { workspaceService } from '../services/workspaceService';
import { adaptTableRecords } from '../adapters/tableRecordsAdapter';
import { buildRecordsQueryParams } from '../records/adapters/recordFiltersAdapter';

/**
 * Loads form field schema + lead records for a workspace table.
 */
export default function useTableRecords({
  workspaceId,
  tableId,
  formItems,
  search = '',
  page = 0,
  pageSize = 10,
  sortBy = '',
  sortType = '',
  filters = {},
  refreshToken = 0,
}) {
  const [columns, setColumns] = useState([]);
  const [rows, setRows] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [uniquePhoneCount, setUniquePhoneCount] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [formPayload, setFormPayload] = useState(null);
  const requestIdRef = useRef(0);

  const applySocketNotification = useCallback((payload) => {
    const notificationType =
      payload?.type === 'notification'
        ? payload?.notification_type
        : payload?.notification_type;

    if (!notificationType || !formPayload || columns.length === 0) {
      return;
    }

    const incoming = Array.isArray(payload?.data) ? payload.data : [payload?.data].filter(Boolean);

    if (notificationType === 'new_leads') {
      const adapted = adaptTableRecords(formPayload, { list: incoming });
      if (!adapted?.rows?.length) return;

      setRows((prevRows) => {
        const incomingIds = new Set(adapted.rows.map((row) => String(row.id)));
        const kept = prevRows.filter((row) => !incomingIds.has(String(row.id)));
        return [...adapted.rows, ...kept];
      });
      setTotalCount((count) => count + adapted.rows.length);
      return;
    }

    if (notificationType === 'update_leads') {
      const adapted = adaptTableRecords(formPayload, { list: incoming });
      const incomingRows = adapted?.rows ?? [];
      if (!incomingRows.length) return;

      setRows((prevRows) => prevRows.map((row) => {
        const match = incomingRows.find((candidate) => String(candidate.id) === String(row.id));
        return match ? { ...row, ...match } : row;
      }));
      return;
    }

    if (notificationType === 'bulk_update_leads') {
      const adapted = adaptTableRecords(formPayload, { list: incoming });
      const incomingRows = adapted?.rows ?? [];
      if (!incomingRows.length) return;

      setRows((prevRows) => {
        const next = [...prevRows];
        incomingRows.forEach((row) => {
          const idx = next.findIndex((item) => String(item.id) === String(row.id));
          if (idx >= 0) {
            next[idx] = { ...next[idx], ...row };
          }
        });
        return next;
      });
      return;
    }

    if (notificationType === 'delete_leads') {
      const remoteIds = incoming
        .map((entry) => String(entry?.id ?? entry?.lead_id ?? entry?._id ?? entry?.record_id ?? ''))
        .filter(Boolean);

      if (!remoteIds.length) return;

      setRows((prevRows) => prevRows.filter((row) => !remoteIds.includes(String(row.id))));
      setTotalCount((count) => Math.max(count - remoteIds.length, 0));
    }
  }, [columns.length, formPayload]);

  const fetchRecords = useCallback(async () => {
    const requestId = requestIdRef.current + 1;
    requestIdRef.current = requestId;

    if (!workspaceId || !tableId) {
      setColumns([]);
      setRows([]);
      setTotalCount(0);
      setUniquePhoneCount(0);
      setError(null);
      setFormPayload(null);
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const queryParams = buildRecordsQueryParams({
        workspaceId,
        tableId,
        search,
        page,
        pageSize,
        sortBy,
        sortType,
        filters,
      });

      const recordsPromise = workspaceService.getTableRecords(workspaceId, tableId, queryParams);

      const hasCachedFormItems = formItems && (
        Array.isArray(formItems)
          ? formItems.length > 0
          : Object.keys(formItems).length > 0
      );

      let nextFormPayload = hasCachedFormItems ? { leads_form_items: formItems } : null;

      if (!nextFormPayload) {
        const formRes = await workspaceService.getLeadFormById(tableId);
        if (formRes?.status === 200 || formRes?.status === 201) {
          nextFormPayload = formRes.data;
        }
      }

      const recordsRes = await recordsPromise;

      if (recordsRes?.status !== 200 && recordsRes?.status !== 201) {
        throw new Error('Unable to load table records');
      }

      const adapted = adaptTableRecords(nextFormPayload, recordsRes.data);
      if (requestId !== requestIdRef.current) return;

      setFormPayload(nextFormPayload);
      setColumns(adapted.columns);
      setRows(adapted.rows);
      setTotalCount(adapted.totalCount);
      setUniquePhoneCount(adapted.uniquePhoneCount);
    } catch (err) {
      if (requestId !== requestIdRef.current) return;

      setColumns([]);
      setRows([]);
      setTotalCount(0);
      setUniquePhoneCount(0);
      setFormPayload(null);
      setError(
        err?.response?.data?.message
        || err?.message
        || 'Unable to load table records'
      );
    } finally {
      if (requestId === requestIdRef.current) {
        setIsLoading(false);
      }
    }
  }, [
    workspaceId,
    tableId,
    formItems,
    search,
    page,
    pageSize,
    sortBy,
    sortType,
    filters,
    refreshToken,
  ]);

  useEffect(() => {
    fetchRecords();
  }, [fetchRecords]);

  return {
    columns,
    rows,
    totalCount,
    uniquePhoneCount,
    isLoading,
    error,
    formPayload,
    refetch: fetchRecords,
    applySocketNotification,
  };
}
