import React from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import DownloadIcon from '@mui/icons-material/Download';
import EditOutlinedIcon from '@mui/icons-material/EditOutlined';
import UploadFileIcon from '@mui/icons-material/UploadFile';
import { RECORD_COPY } from '../constants/recordCopy';
import RecordToolbarIconButton from './RecordToolbarIconButton';

/**
 * Permission-gated record toolbar icons shown beside Refresh.
 */
export default function RecordToolbarIconActions({
  permissions = {},
  onDownload,
  onImportRecords,
  onEditForm,
  onEnterRecords,
}) {
  return (
    <>
      {permissions.canDownload ? (
        <RecordToolbarIconButton
          title={RECORD_COPY.actions.download}
          ariaLabel={RECORD_COPY.actions.download}
          onClick={onDownload}
          icon={<DownloadIcon />}
        />
      ) : null}

      {permissions.canImport ? (
        <RecordToolbarIconButton
          title={RECORD_COPY.actions.importRecords}
          ariaLabel={RECORD_COPY.actions.importRecords}
          onClick={onImportRecords}
          icon={<UploadFileIcon />}
        />
      ) : null}

      {permissions.canEditForm ? (
        <RecordToolbarIconButton
          title={RECORD_COPY.actions.editForm}
          ariaLabel={RECORD_COPY.actions.editForm}
          onClick={onEditForm}
          icon={<EditOutlinedIcon />}
        />
      ) : null}

      {permissions.canEnterRecords ? (
        <RecordToolbarIconButton
          title={RECORD_COPY.actions.enterRecords}
          ariaLabel={RECORD_COPY.actions.enterRecords}
          onClick={onEnterRecords}
          icon={<AddCircleOutlineIcon />}
        />
      ) : null}
    </>
  );
}
